const EOTC_EVANGELISTS = [
    { index: 0, en: 'John',    am: 'ዘመነ ዮሐንስ', tg: 'ዘመነ ዮሃንስ' }, // ethYear % 4 === 0 (leap year with Pagumen 6: wait — in EC, year % 4 === 3 has 6 Pagumen days!)
    { index: 1, en: 'Matthew', am: 'ዘመነ ማቴዎስ', tg: 'ዘመነ ማቴዎስ' },
    { index: 2, en: 'Mark',    am: 'ዘመነ ማርቆስ', tg: 'ዘመነ ማርቆስ' },
    { index: 3, en: 'Luke',    am: 'ዘመነ ሉቃስ',  tg: 'ዘመነ ሉቃስ' }
];

const EOTC_ETH_MONTH_NAMES_SHORT = [
    '', 'Meskerem', 'Tikimt', 'Hidar', 'Tahsas', 'Tir', 'Yekatit',
    'Megabit', 'Miyazya', 'Ginbot', 'Sene', 'Hamle', 'Nehasse', 'Pagumen'
];

const EOTC_ETH_MONTH_NAMES_GEEZ = [
    '', 'መስከረም', 'ጥቅምት', 'ኅዳር', 'ታኅሣሥ', 'ጥር', 'የካቲት',
    'መጋቢት', 'ሚያዝያ', 'ግንቦት', 'ሰኔ', 'ሐምሌ', 'ነሐሴ', 'ጳጉሜን'
];

function isEthiopianLeapYear(ethYear) {
    return ((Number(ethYear) % 4) + 4) % 4 === 3;
}

function ethiopianDaysInMonth(ethYear, ethMonth) {
    if (ethMonth >= 1 && ethMonth <= 12) return 30;
    return isEthiopianLeapYear(ethYear) ? 6 : 5;
}

function ethiopianToJdn(ethYear, ethMonth, ethDay) {
    const y = Number(ethYear);
    const m = Number(ethMonth);
    const d = Number(ethDay);
    return 1723856 + 365 * y + Math.floor(y / 4) + 30 * m + d - 31;
}

function jdnToEthiopian(jdn) {
    const r = (jdn - 1723856) % 1461;
    const rPos = r < 0 ? r + 1461 : r;
    const n = (rPos % 365) + 365 * Math.floor(rPos / 1460);
    const year = 4 * Math.floor((jdn - 1723856) / 1461) + Math.floor(rPos / 365) - Math.floor(rPos / 1460);
    const month = Math.floor(n / 30) + 1;
    const day = (n % 30) + 1;
    return { year, month, day };
}

function gregorianYmdToJdn(year, month, day) {
    const a = Math.floor((14 - month) / 12);
    const y = year + 4800 - a;
    const m = month + 12 * a - 3;
    return day + Math.floor((153 * m + 2) / 5) + 365 * y + Math.floor(y / 4) - Math.floor(y / 100) + Math.floor(y / 400) - 32045;
}

function addEthiopianDays(ethDate, deltaDays) {
    return jdnToEthiopian(ethiopianToJdn(ethDate.year, ethDate.month, ethDate.day) + deltaDays);
}

function compareEthiopianDates(a, b) {
    if (a.year !== b.year) return a.year < b.year ? -1 : 1;
    if (a.month !== b.month) return a.month < b.month ? -1 : 1;
    if (a.day !== b.day) return a.day < b.day ? -1 : 1;
    return 0;
}

function ethiopianWeekdayIndex(ethDate) {
    // 0 = Sunday, 1 = Monday, ..., 6 = Saturday
    const jdn = ethiopianToJdn(ethDate.year, ethDate.month, ethDate.day);
    return ((jdn + 1) % 7 + 7) % 7;
}

const _bahireHasabCache = {};

function computeEotcBahireHasab(ethYear) {
    const y = Number(ethYear);
    if (!Number.isFinite(y)) return null;
    if (_bahireHasabCache[y]) return _bahireHasabCache[y];

    const gregYear = y + EOTC_BAHIRE_HASAB_CONFIG.gregorianYearOfTinsaeOffset;
    // Meeus Julian Easter computus
    const a = ((gregYear % 4) + 4) % 4;
    const b = ((gregYear % 7) + 7) % 7;
    const c = ((gregYear % 19) + 19) % 19;
    const d = (19 * c + 15) % 30;
    const e = (2 * a + 4 * b - d + 34) % 7;
    const raw = d + e + 114;
    const julianMonth = Math.floor(raw / 31);
    const julianDay = (raw % 31) + 1;

    const easterJdn = gregorianYmdToJdn(gregYear, julianMonth, julianDay) + EOTC_BAHIRE_HASAB_CONFIG.julianToGregorianDays;
    const tinsae = jdnToEthiopian(easterJdn);
    const ninevehJdn = easterJdn - EOTC_BAHIRE_HASAB_CONFIG.ninevehToTinsaeDays;
    const nineveh = jdnToEthiopian(ninevehJdn);

    const moveableDates = {};
    for (const item of EOTC_BAHIRE_HASAB_CONFIG.offsetsFromNineveh) {
        moveableDates[item.key] = jdnToEthiopian(ninevehJdn + item.daysFromNineveh);
    }

    // Evangelist cycle: (ethYear + 5500) % 4 => 1=Matthew, 2=Mark, 3=Luke, 0=John
    const evIdx = (((y + 5500) % 4) + 4) % 4;
    const ev = EOTC_EVANGELISTS[evIdx] || EOTC_EVANGELISTS[0];

    const result = {
        year: y,
        gregorianEasterYear: gregYear,
        evangelist: ev,
        ninevehJdn,
        easterJdn,
        tinsae,
        nineveh,
        moveableDates
    };
    _bahireHasabCache[y] = result;
    return result;
}

// ============================================================================
// Feasts & Comprehensive EOTC Fasting Engine (Bete Tselot + 7 Canonical Fasts)
// ============================================================================

function getEotc2014FeastsForDate(ethYear, ethMonth, ethDay) {
    const y = Number(ethYear);
    const m = Number(ethMonth);
    const d = Number(ethDay);
    const bh = computeEotcBahireHasab(y);
    const matched = [];

    for (const f of EOTC_FEASTS_REGISTRY.fixed) {
        if (f.month === m && f.day === d) {
            matched.push({ ...f, type: 'fixed' });
        }
    }
    if (bh && bh.moveableDates) {
        for (const f of EOTC_FEASTS_REGISTRY.moveable) {
            const md = bh.moveableDates[f.moveableKey];
            if (md && md.month === m && md.day === d) {
                matched.push({ ...f, type: 'moveable' });
            }
        }
    }
    const monthlySaint = (d >= 1 && d <= 30) ? (EOTC_MONTHLY_SAINTS[String(d)] || null) : null;
    return { feasts: matched, monthlySaint };
}

function getEotc2014SpecialFastMatch(ethYear, ethMonth, ethDay) {
    const bh = computeEotcBahireHasab(ethYear);
    if (!bh) return null;
    const targetJdn = ethiopianToJdn(ethYear, ethMonth, ethDay);
    const daysFromNineveh = targetJdn - bh.ninevehJdn;

    // 1. Fast of Nineveh
    const ninFast = EOTC_GITSAWE_2014_FASTS.nineveh;
    if (ninFast) {
        const dayEntry = ninFast.days.find(x => x.dayOffset === daysFromNineveh);
        if (dayEntry) {
            return { fastId: 'nineveh', fastName: ninFast.name, dayOffset: daysFromNineveh, day: dayEntry };
        }
    }

    // 2. Abiy Tsom / Great Lent + Zewerede (-1) + Holy Week + Tinsae (+55) + Dagim Tinsae (+62)
    const abiyOffset = daysFromNineveh - 14;
    const abiyFast = EOTC_GITSAWE_2014_FASTS.abiyTsom;
    if (abiyFast) {
        const dayEntry = abiyFast.days.find(x => x.dayOffset === abiyOffset);
        if (dayEntry) {
            return { fastId: 'abiyTsom', fastName: abiyFast.name, dayOffset: abiyOffset, day: dayEntry };
        }
    }
    return null;
}

/**
 * Evaluates whether a given Ethiopian date is a fasting day in the EOTC,
 * combining Bete Tselot's moveable-fast metadata with all 7 canonical EOTC
 * fasting seasons (ሰባቱ አጽዋማት) and the 50-day Paschal fast-free season.
 */
function getEotcFastingStatus(ethYear, ethMonth, ethDay, explicitWeekdayIdx = null) {
    const y = Number(ethYear);
    const m = Number(ethMonth);
    const d = Number(ethDay);
    const ethDate = { year: y, month: m, day: d };
    const weekday = (explicitWeekdayIdx !== null && explicitWeekdayIdx !== undefined)
        ? Number(explicitWeekdayIdx)
        : ethiopianWeekdayIndex(ethDate);

    const bh = computeEotcBahireHasab(y);
    const { feasts } = getEotc2014FeastsForDate(y, m, d);
    const specialFast = getEotc2014SpecialFastMatch(y, m, d);
    const targetJdn = ethiopianToJdn(y, m, d);
    const daysFromNineveh = bh ? (targetJdn - bh.ninevehJdn) : null;

    const activeFasts = [];
    let isFastFreeSeason = false;
    let fastFreeReason = null;

    // Genna falls on Tahsas 28 after a leap year (Zemene Yohannes, i.e., when previous year was Luke)
    const gennaDay = isEthiopianLeapYear(y - 1) ? 28 : 29;
    const isGenna = (m === 4 && d === gennaDay);
    const isTimket = (m === 5 && d === 11);

    // 1. 50-Day Paschal Season (Tinsae through Paraclete = Nineveh+69 .. Nineveh+118): Fast-Free!
    if (daysFromNineveh !== null && daysFromNineveh >= 69 && daysFromNineveh <= 118) {
        isFastFreeSeason = true;
        fastFreeReason = 'Season of the Resurrection (በዓለ ኀምሳ / ዘመነ ትንሣኤ)';
    } else if (isGenna) {
        isFastFreeSeason = true;
        fastFreeReason = 'Feast of the Nativity (በዓለ ልደት / ገና)';
    } else if (isTimket) {
        isFastFreeSeason = true;
        fastFreeReason = 'Feast of Theophany (በዓለ ጥምቀት)';
    }

    if (!isFastFreeSeason) {
        // (a) Fast of Nineveh (ጾመ ነነዌ): 3 days (Nineveh + 0..2)
        if (daysFromNineveh !== null && daysFromNineveh >= 0 && daysFromNineveh <= 2) {
            activeFasts.push({
                id: 'tsome_nenewe',
                nameEn: 'Fast of Nineveh',
                nameAm: 'ጾመ ነነዌ',
                nameTg: 'ጾመ ነነዌ',
                dayNumber: daysFromNineveh + 1,
                totalDays: 3
            });
        }

        // (b) Great Lent & Holy Week (ዐቢይ ጾም / ሰሞነ ሕማማት): 55 days (Nineveh+14 .. Nineveh+68)
        if (daysFromNineveh !== null && daysFromNineveh >= 14 && daysFromNineveh <= 68) {
            const lentDay = daysFromNineveh - 13;
            const isHolyWeek = daysFromNineveh >= 63; // Monday after Hosanna through Qidame Si'ur
            activeFasts.push({
                id: isHolyWeek ? 'semone_himamat' : 'abiy_tsom',
                nameEn: isHolyWeek ? 'Holy Week (Great Lent)' : 'Great Lent (Abiy Tsom)',
                nameAm: isHolyWeek ? 'ሰሞነ ሕማማት (ዐቢይ ጾም)' : 'ዐቢይ ጾም',
                nameTg: isHolyWeek ? 'ሰሙነ ሕማማት (ዓቢይ ጾም)' : 'ዓቢይ ጾም',
                dayNumber: lentDay,
                totalDays: 55
            });
        }

        // (c) Fast of the Apostles (ጾመ ሐዋርያት): Monday after Pentecost (Nineveh+119) through Hamle 4 (11/4)
        if (bh && daysFromNineveh !== null && daysFromNineveh >= 119) {
            const hamle4Jdn = ethiopianToJdn(y, 11, 4);
            if (targetJdn <= hamle4Jdn) {
                const startJdn = bh.ninevehJdn + 119;
                activeFasts.push({
                    id: 'tsome_hawariyat',
                    nameEn: "Fast of the Apostles",
                    nameAm: 'ጾመ ሐዋርያት',
                    nameTg: 'ጾመ ሐዋርያት',
                    dayNumber: targetJdn - startJdn + 1,
                    totalDays: hamle4Jdn - startJdn + 1
                });
            }
        }

        // (d) Fast of the Assumption of St. Mary (ጾመ ፍልሰታ): Nehasse 1 – 15 (12/1 .. 12/15)
        if (m === 12 && d >= 1 && d <= 15) {
            activeFasts.push({
                id: 'tsome_filseta',
                nameEn: 'Fast of the Assumption (Filseta)',
                nameAm: 'ጾመ ፍልሰታ',
                nameTg: 'ጾመ ፍልሰታ',
                dayNumber: d,
                totalDays: 15
            });
        }

        // (e) Fast of the Prophets / Advent (ጾመ ነቢያት): Hidar 15 (3/15) – Eve of Genna (4/27 or 4/28)
        const gennaEveDay = gennaDay - 1;
        if ((m === 3 && d >= 15) || (m === 4 && d <= gennaEveDay)) {
            const startJdn = ethiopianToJdn(y, 3, 15);
            const endJdn = ethiopianToJdn(y, 4, gennaEveDay);
            activeFasts.push({
                id: 'tsome_nebiyat',
                nameEn: 'Fast of the Prophets (Advent)',
                nameAm: 'ጾመ ነቢያት',
                nameTg: 'ጾመ ነቢያት',
                dayNumber: targetJdn - startJdn + 1,
                totalDays: endJdn - startJdn + 1
            });
        }

        // (f) Gahad / Paramony (ጾመ ገሀድ): Eve of Genna & Eve of Timket (5/10)
        if ((m === 4 && d === gennaEveDay) || (m === 5 && d === 10)) {
            activeFasts.push({
                id: 'tsome_gahad',
                nameEn: m === 5 ? 'Paramony of Theophany (Gahad)' : 'Paramony of Nativity (Gahad)',
                nameAm: 'ጾመ ገሀድ',
                nameTg: 'ጾመ ገሃድ'
            });
        }

        // (g) Weekly Fast of Salvation (ጾመ ድኅነት): Wednesdays (3) & Fridays (5) outside Fast-Free days
        if (weekday === 3 || weekday === 5) {
            activeFasts.push({
                id: 'tsome_dihnet',
                nameEn: weekday === 3 ? 'Wednesday Fast of Salvation' : 'Friday Fast of Salvation',
                nameAm: 'ጾመ ድኅነት',
                nameTg: 'ጾመ ድሕነት'
            });
        }
    }

    const fastFeastIds = feasts.filter(f => f.category === 'fast').map(f => f.id);
    return {
        isFastingDay: activeFasts.length > 0,
        activeFasts,
        primaryFast: activeFasts[0] || null,
        isFastFreeSeason,
        fastFreeReason,
        fastFeastIds,
        specialFastId: specialFast ? specialFast.fastId : null,
        specialFastDayOffset: specialFast ? specialFast.dayOffset : null,
        specialFastSection: specialFast ? specialFast.day.sectionName : null
    };
}

// ============================================================================
// Seasonal Sunday Resolution (including Lay Bet / Tach Bet Ordinal Neighbors)
// ============================================================================

function _sundaysBeforeFeast(ethDate, anchorMonth, anchorDay) {
    const feast = { year: ethDate.year, month: anchorMonth, day: anchorDay };
    if (compareEthiopianDates(ethDate, feast) >= 0) return 0;
    let lastSun = addEthiopianDays(feast, -1);
    while (ethiopianWeekdayIndex(lastSun) !== 0) {
        lastSun = addEthiopianDays(lastSun, -1);
    }
    const diff = ethiopianToJdn(lastSun.year, lastSun.month, lastSun.day) - ethiopianToJdn(ethDate.year, ethDate.month, ethDate.day);
    if (diff < 0 || diff % 7 !== 0) return 0;
    return Math.floor(diff / 7) + 1;
}

function _ordinalSundayInSeason(ethDate, season) {
    if (!season) return 0;
    const bh = computeEotcBahireHasab(ethDate.year);
    let start = null;
    if (season.startFeast) {
        start = bh && bh.moveableDates ? bh.moveableDates[season.startFeast] : null;
        if (!start) return 0;
    } else {
        start = { year: ethDate.year, month: season.startMonth, day: season.startDay };
    }
    if (compareEthiopianDates(ethDate, start) < 0) return 0;

    if (season.endFeast) {
        const end = bh && bh.moveableDates ? bh.moveableDates[season.endFeast] : null;
        if (!end) return 0;
        if (compareEthiopianDates(ethDate, end) >= 0) return 0;
    } else {
        const end = { year: ethDate.year, month: season.endMonth, day: season.endDay };
        if (compareEthiopianDates(ethDate, end) > 0) return 0;
    }

    let firstSun = start;
    while (ethiopianWeekdayIndex(firstSun) !== 0) {
        firstSun = addEthiopianDays(firstSun, 1);
    }
    const diff = ethiopianToJdn(ethDate.year, ethDate.month, ethDate.day) - ethiopianToJdn(firstSun.year, firstSun.month, firstSun.day);
    if (diff < 0 || diff % 7 !== 0) return 0;
    return Math.floor(diff / 7) + 1;
}

function getEotc2014SundayMatches(ethYear, ethMonth, ethDay, explicitWeekdayIdx = null) {
    const ethDate = { year: Number(ethYear), month: Number(ethMonth), day: Number(ethDay) };
    const wd = (explicitWeekdayIdx !== null && explicitWeekdayIdx !== undefined)
        ? Number(explicitWeekdayIdx)
        : ethiopianWeekdayIndex(ethDate);
    if (wd !== 0) return { primary: null, alternates: [] };

    let exactMatch = null;
    let beforeFeastMatch = null;
    let ordinalMatch = null;
    let rangeMatch = null;

    for (const s of EOTC_GITSAWE_2014_SUNDAYS) {
        const r = s.rule;
        if (!exactMatch && r.kind === 'exact' && s.month === ethDate.month && ethDate.day >= r.from && ethDate.day <= r.to) {
            exactMatch = s;
        }
        if (!beforeFeastMatch && r.kind === 'beforeFeast' && _sundaysBeforeFeast(ethDate, r.anchorMonth, r.anchorDay) === r.ordinal) {
            beforeFeastMatch = s;
        }
        if (!ordinalMatch && r.kind === 'ordinal' && r.season && _ordinalSundayInSeason(ethDate, r.season) === r.ordinal) {
            ordinalMatch = s;
        }
        if (!rangeMatch && r.kind === 'range' && s.month === ethDate.month && ethDate.day >= r.from && ethDate.day <= r.to) {
            rangeMatch = s;
        }
    }

    const primary = exactMatch || beforeFeastMatch || ordinalMatch || rangeMatch || null;
    const alternates = [];
    const pushAlt = (sec, reason) => {
        if (!sec || !sec.qidase) return;
        if (primary && sec.index === primary.index) return;
        if (alternates.some(a => a.section.index === sec.index)) return;
        alternates.push({ section: sec, reason });
    };

    // If an exact date Sunday rule matched (e.g. Tikimt 17/19/29, Meskerem 8/16/24/25),
    // also offer the underlying seasonal Sunday (ordinal or range) for parishes using the season cycle!
    if (primary === exactMatch) {
        if (ordinalMatch) pushAlt(ordinalMatch, 'Seasonal Sunday');
        if (rangeMatch) pushAlt(rangeMatch, 'Seasonal Sunday');
    }

    // For ordinal seasonal Sundays (e.g. Zemene Tsige, Post-Nativity, Post-Tinsae, Kiremt),
    // include adjacent ordinal Mezmur sections (n-1 and n+1) in the same file so both
    // Tach Bet and Lay Bet parish Sunday counts are 1 tap away!
    const activeOrdinal = ordinalMatch || (primary && primary.rule.kind === 'ordinal' ? primary : null);
    if (activeOrdinal) {
        const n = activeOrdinal.rule.ordinal;
        const src = activeOrdinal.source;
        const prevSec = EOTC_GITSAWE_2014_SUNDAYS.find(s => s.source === src && s.rule.kind === 'ordinal' && s.rule.ordinal === n - 1);
        const nextSec = EOTC_GITSAWE_2014_SUNDAYS.find(s => s.source === src && s.rule.kind === 'ordinal' && s.rule.ordinal === n + 1);
        if (prevSec) pushAlt(prevSec, src === 'sunday_tikimt' ? 'Tach Bet / Prev Mezmur' : 'Prev Sunday Mezmur');
        if (nextSec) pushAlt(nextSec, src === 'sunday_tikimt' ? 'Lay Bet / Next Mezmur' : 'Next Sunday Mezmur');
    }

    return { primary, alternates };
}

function getEotc2014DailyEntry(ethMonth, ethDay) {
    const key = `${parseInt(ethMonth, 10)}/${parseInt(ethDay, 10)}`;
    return EOTC_GITSAWE_2014_DAILY[key] || null;
}

// ============================================================================
// Parish-Ready Qidase Reading Profiles Builder (Scroll & Slides Mode Toggles)
// ============================================================================

const DEFAULT_MATINS_REFS = {
    morningPsalm: 'Psalms 34:7-8',
    morningGospel: 'Matthew 24:30-36',
    eveningPsalm: 'Psalms 141:2',
    eveningGospel: 'Luke 4:38-41'
};

const _LENT_SUNDAY_LABELS = {
    '-1': { en: 'Zewerede (1st Lent)', gz: 'ዘወረደ' },
    6:    { en: 'Qidist (2nd Lent)',   gz: 'ቅድስት' },
    13:   { en: 'Mukurab (3rd Lent)',  gz: 'ምኩራብ' },
    20:   { en: 'Metsagu (4th Lent)',  gz: 'መጻጉዕ' },
    27:   { en: 'Debre Zeit (5th Lent)', gz: 'ደብረ ዘይት' },
    34:   { en: 'Gebre Her (6th Lent)', gz: 'ገብረ ኄር' },
    41:   { en: 'Niqodimos (7th Lent)', gz: 'ኒቆዲሞስ' },
    48:   { en: 'Hosanna (Palm Sunday)', gz: 'ሆሣዕና' },
    55:   { en: 'Tinsae (Pascha)',     gz: 'ትንሣኤ' },
    62:   { en: 'Dagim Tinsae',        gz: 'ዳግም ትንሣኤ' }
};

function _formatSundayShortLabel(sec, rolePrefix = '') {
    if (!sec) return rolePrefix || 'Sunday';
    const src = sec.source || '';
    const r = sec.rule || {};
    let base = 'Sunday';
    if (src === 'sunday_tikimt') {
        base = r.kind === 'ordinal' ? `Tsige ${r.ordinal}` : 'Tsige Sunday';
    } else if (src === 'sunday_tahsas') {
        if (r.kind === 'beforeFeast') {
            base = r.ordinal === 3 ? 'Sibket' : (r.ordinal === 2 ? 'Birhan' : 'Nolawi');
        } else {
            base = 'Tahsas Sunday';
        }
    } else if (src === 'sunday_tir_yekatit') {
        base = r.kind === 'ordinal' ? `Epiphany ${r.ordinal}` : 'Sunday';
    } else if (src === 'sunday_trinsae') {
        if (r.kind === 'ordinal') {
            base = r.ordinal === 8 ? 'Pentecost' : `Pascha ${r.ordinal}`;
        } else {
            base = 'Sunday';
        }
    } else if (src === 'sunday_kiremet') {
        base = r.kind === 'ordinal' ? `Kiremt ${r.ordinal}` : 'Kiremt Sunday';
    } else if (src === 'sunday_meskerem') {
        base = (r.from >= 16 && r.to <= 25) ? 'Meskel Sunday' : 'Meskerem Sunday';
    } else if (src === 'sunday_hidar') {
        base = 'Hidar Sunday';
    }
    return rolePrefix ? `${rolePrefix} (${base})` : `Sunday (${base})`;
}

function _parseLxxStringMeta(psalmLxx, psalmText) {
    if (!psalmLxx) return null;
    const m = String(psalmLxx).match(/^(\d+):(\d+)(?:-(\d+))?$/);
    if (!m) return null;
    const lc = parseInt(m[1], 10);
    const ls = parseInt(m[2], 10);
    const le = m[3] ? parseInt(m[3], 10) : ls;
    return { lc, ls, le, psalmLxx, g: psalmText || '' };
}

function _buildProfileFromDayNode(opts) {
    const {
        id, category, shortLabel, shortLabelGeez = '', subtitle = '', commemoration = '',
        dayNode, fallbackDayNode, convertLxxFn, useAlt = false
    } = opts;

    const q = (dayNode && dayNode.qidase) || {};
    const qAlt = (useAlt && q.alt) ? q.alt : {};
    const mNode = (dayNode && dayNode.morning) || (fallbackDayNode && fallbackDayNode.morning) || null;
    const mAlt = (useAlt && mNode && mNode.alt) ? mNode.alt : {};
    const eNode = (dayNode && dayNode.evening) || (fallbackDayNode && fallbackDayNode.evening) || null;
    const eAlt = (useAlt && eNode && eNode.alt) ? eNode.alt : {};
    const fbQ = (fallbackDayNode && fallbackDayNode.qidase) || {};

    const toMt = (lxx) => {
        if (!lxx) return null;
        if (typeof convertLxxFn === 'function') return convertLxxFn(lxx);
        if (typeof window !== 'undefined' && typeof window.convertLxxPsalmRefToMt === 'function') {
            return window.convertLxxPsalmRefToMt(lxx);
        }
        return null;
    };

    const mornLxx = mAlt.psalmLxx || (mNode && mNode.psalmLxx) || null;
    const mornText = mAlt.psalmText || (mNode && mNode.psalmText) || '';
    const mornGospel = mAlt.gospel || (mNode && mNode.gospel) || DEFAULT_MATINS_REFS.morningGospel;

    const qLxx = qAlt.psalmLxx || q.psalmLxx || fbQ.psalmLxx || '117:26-27';
    const qText = qAlt.psalmText || q.psalmText || fbQ.psalmText || '';

    const eveLxx = eAlt.psalmLxx || (eNode && eNode.psalmLxx) || null;
    const eveText = eAlt.psalmText || (eNode && eNode.psalmText) || '';
    const eveGospel = eAlt.gospel || (eNode && eNode.gospel) || DEFAULT_MATINS_REFS.eveningGospel;

    const refs = {
        morningPsalm: (mornLxx && toMt(mornLxx)) || DEFAULT_MATINS_REFS.morningPsalm,
        morningGospel: mornGospel,
        pauline: qAlt.pauline || q.pauline || fbQ.pauline || '1 Corinthians 1:10-End',
        universal: qAlt.universal || q.universal || fbQ.universal || '1 Peter 1:1-12',
        acts: qAlt.acts || q.acts || fbQ.acts || 'Acts 2:38-47',
        psalm: toMt(qLxx) || 'Psalms 118:26-27',
        gospel: qAlt.gospel || q.gospel || fbQ.gospel || 'John 1:1-18',
        eveningPsalm: (eveLxx && toMt(eveLxx)) || DEFAULT_MATINS_REFS.eveningPsalm,
        eveningGospel: eveGospel
    };

    const psalmMeta = {};
    if (mornLxx) psalmMeta.morningPsalm = _parseLxxStringMeta(mornLxx, mornText);
    if (qLxx) psalmMeta.psalm = _parseLxxStringMeta(qLxx, qText);
    if (eveLxx) psalmMeta.eveningPsalm = _parseLxxStringMeta(eveLxx, eveText);

    // Expose per-slot ዓዲ alternates when available on the base dayNode
    const slotAlternates = {};
    if (q.alt) {
        if (q.alt.pauline) slotAlternates.pauline = { ref: q.alt.pauline, primaryRef: q.pauline };
        if (q.alt.universal) slotAlternates.universal = { ref: q.alt.universal, primaryRef: q.universal };
        if (q.alt.acts) slotAlternates.acts = { ref: q.alt.acts, primaryRef: q.acts };
        if (q.alt.psalmLxx) {
            slotAlternates.psalm = {
                ref: toMt(q.alt.psalmLxx),
                psalmLxx: q.alt.psalmLxx,
                psalmText: q.alt.psalmText || '',
                primaryRef: toMt(q.psalmLxx)
            };
        }
        if (q.alt.gospel) slotAlternates.gospel = { ref: q.alt.gospel, primaryRef: q.gospel };
    }

    const anaphoraId = q.anaphora || fbQ.anaphora || 1;
    const anaphoraAlts = q.anaphoraAlts || fbQ.anaphoraAlts || [];
    const liturgyTypeGeez = q.liturgyType || fbQ.liturgyType || '';

    return {
        id,
        category,
        shortLabel,
        shortLabelGeez,
        subtitle,
        commemoration: commemoration || (dayNode && dayNode.commemoration) || '',
        anaphoraId,
        anaphoraAlts,
        liturgyTypeGeez,
        psalmLxx: qLxx,
        refs,
        psalmMeta,
        slotAlternates
    };
}

function _signatureOfRefs(refs) {
    return `${refs.pauline}|${refs.universal}|${refs.acts}|${refs.psalm}|${refs.gospel}`;
}

/**
 * Returns all candidate Qidase reading profiles for a given Ethiopian date,
 * ordered with the official 2013/14 Patriarchate primary selection at index 0
 * and parish/house alternates immediately accessible at indices 1..N.
 */
function getEotcKidaseProfilesForDate(ethYear, ethMonth, ethDay, explicitWeekdayIdx = null, convertLxxFn = null, legacy1938Entry = null) {
    const y = Number(ethYear);
    const m = Number(ethMonth);
    const d = Number(ethDay);
    const ethDate = { year: y, month: m, day: d };
    const wd = (explicitWeekdayIdx !== null && explicitWeekdayIdx !== undefined)
        ? Number(explicitWeekdayIdx)
        : ethiopianWeekdayIndex(ethDate);

    const daily2014 = getEotc2014DailyEntry(m, d);
    const monthNameEn = EOTC_ETH_MONTH_NAMES_SHORT[m] || `M${m}`;
    const monthNameGz = EOTC_ETH_MONTH_NAMES_GEEZ[m] || '';
    const dailyLabel = `Daily (${monthNameEn} ${d})`;

    const profiles = [];
    const seenSignatures = new Set();

    const addProfile = (prof, allowDuplicateSig = false) => {
        if (!prof || !prof.refs) return;
        const sig = _signatureOfRefs(prof.refs);
        if (!allowDuplicateSig && seenSignatures.has(sig)) return;
        seenSignatures.add(sig);
        profiles.push(prof);
    };

    // Major Fixed Feasts of Our Lord where the 2013/14 Gitsawe explicitly directs
    // reading the fixed feast Qidase even when falling on a Sunday:
    //   1/17 Meskel, 4/28-29 Genna, 5/11 Timket, 12/13 Debre Tabor
    const gennaDay = isEthiopianLeapYear(y - 1) ? 28 : 29;
    const isFixedLordFeastOverridingSunday =
        (m === 1 && d === 17) ||
        (m === 4 && (d === 28 || d === 29)) ||
        (m === 5 && d === 11) ||
        (m === 12 && d === 13);

    // 1. Check Moveable Fasting / Paschal Seasons (Nineveh & Abiy Tsom / Tinsae / Dagim Tinsae)
    const fastMatch = getEotc2014SpecialFastMatch(y, m, d);
    if (fastMatch) {
        const fDay = fastMatch.day;
        if (fDay.groups && fDay.groups.length > 0) {
            // Grouped Paschal / Holy Week feasts: Hosanna (+48), Tinsae (+55), Dagim Tinsae (+62)
            // Find primary ዘቅዳሴ section first!
            const lentMeta = _LENT_SUNDAY_LABELS[fastMatch.dayOffset];
            const primaryTitle = lentMeta ? lentMeta.en : fDay.sectionName;
            const primaryGz = lentMeta ? lentMeta.gz : fDay.sectionName;

            let qidaseSub = null;
            let matinsSub = null;
            const extraSubs = [];

            for (const grp of fDay.groups) {
                for (const sub of grp.sections) {
                    if (!qidaseSub && sub.qidase && (grp.label.includes('ቅዳሴ') || sub.label.includes('ቅዳሴ') || sub.label.includes('እምድኅረ ትንሣኤ'))) {
                        qidaseSub = sub;
                    } else if (!matinsSub && sub.morning) {
                        matinsSub = sub;
                    } else if (sub.qidase) {
                        extraSubs.push({ grpLabel: grp.label, sub });
                    }
                }
            }

            if (qidaseSub) {
                const mergedNode = {
                    commemoration: qidaseSub.commemoration || fDay.sectionName,
                    morning: qidaseSub.morning || (matinsSub && matinsSub.morning) || (daily2014 && daily2014.morning),
                    qidase: qidaseSub.qidase,
                    evening: qidaseSub.evening || (daily2014 && daily2014.evening)
                };
                addProfile(_buildProfileFromDayNode({
                    id: `fast-${fastMatch.fastId}-${fastMatch.dayOffset}`,
                    category: 'fast',
                    shortLabel: primaryTitle,
                    shortLabelGeez: primaryGz,
                    subtitle: `${fDay.sectionName}${mergedNode.qidase.liturgyType ? ' • ' + mergedNode.qidase.liturgyType : ''}`,
                    commemoration: fDay.sectionName,
                    dayNode: mergedNode,
                    fallbackDayNode: daily2014,
                    convertLxxFn
                }));
            }

            for (let idx = 0; idx < extraSubs.length; idx++) {
                const { grpLabel, sub } = extraSubs[idx];
                addProfile(_buildProfileFromDayNode({
                    id: `fast-${fastMatch.fastId}-${fastMatch.dayOffset}-sub-${idx}`,
                    category: 'fast-alt',
                    shortLabel: sub.label || grpLabel,
                    shortLabelGeez: sub.label || grpLabel,
                    subtitle: `${fDay.sectionName} — ${grpLabel}`,
                    commemoration: sub.commemoration || sub.label,
                    dayNode: sub,
                    fallbackDayNode: daily2014,
                    convertLxxFn
                }));
            }
        } else if (fDay.qidase) {
            let shortLbl = fastMatch.fastId === 'nineveh'
                ? `Nineveh (Day ${fastMatch.dayOffset + 1})`
                : (_LENT_SUNDAY_LABELS[fastMatch.dayOffset]?.en || (fastMatch.dayOffset === 52 ? 'Holy Thursday' : (fastMatch.dayOffset === 54 ? 'Qidame Siur' : `Great Lent (Day ${fastMatch.dayOffset + 1})`)));
            let shortGz = fastMatch.fastId === 'nineveh'
                ? 'ዘነነዌ'
                : (_LENT_SUNDAY_LABELS[fastMatch.dayOffset]?.gz || fDay.sectionName);

            addProfile(_buildProfileFromDayNode({
                id: `fast-${fastMatch.fastId}-${fastMatch.dayOffset}`,
                category: 'fast',
                shortLabel: shortLbl,
                shortLabelGeez: shortGz,
                subtitle: `${fastMatch.fastName} — ${fDay.sectionName}`,
                commemoration: fDay.commemoration || fDay.sectionName,
                dayNode: fDay,
                fallbackDayNode: daily2014,
                convertLxxFn
            }));

            if (fDay.qidase.alt) {
                addProfile(_buildProfileFromDayNode({
                    id: `fast-${fastMatch.fastId}-${fastMatch.dayOffset}-alt`,
                    category: 'fast-alt',
                    shortLabel: `${shortLbl} (ዓዲ)`,
                    shortLabelGeez: 'ዓዲ',
                    subtitle: `${fDay.sectionName} — Alternate (ዓዲ)`,
                    commemoration: fDay.commemoration || fDay.sectionName,
                    dayNode: fDay,
                    fallbackDayNode: daily2014,
                    convertLxxFn,
                    useAlt: true
                }));
            }
        }
    }

    // Helper to append Fixed Daily 2014 (+ its ዓዲ alternate)
    const appendDaily2014 = (isPrimaryOnDay = false) => {
        if (!daily2014 || !daily2014.qidase) return;
        const hasAlt = Boolean(daily2014.qidase.alt);
        const primaryPillLabel = isPrimaryOnDay
            ? (m === 1 && d === 17 ? 'Meskel (2014)' : (hasAlt ? '2014 Primary' : `2014 (${monthNameEn} ${d})`))
            : dailyLabel;
        addProfile(_buildProfileFromDayNode({
            id: `daily-2014-${m}-${d}`,
            category: 'daily',
            shortLabel: primaryPillLabel,
            shortLabelGeez: `${monthNameGz} ${d}`,
            subtitle: `${monthNameEn} ${d}${daily2014.commemoration ? ' • ' + daily2014.commemoration : ''}`,
            commemoration: daily2014.commemoration,
            dayNode: daily2014,
            fallbackDayNode: daily2014,
            convertLxxFn,
            useAlt: false
        }));
        if (hasAlt) {
            addProfile(_buildProfileFromDayNode({
                id: `daily-2014-${m}-${d}-alt`,
                category: 'daily-alt',
                shortLabel: isPrimaryOnDay ? 'Alternate (ዓዲ)' : `${dailyLabel} · ዓዲ`,
                shortLabelGeez: 'ዓዲ',
                subtitle: `${monthNameEn} ${d} — Alternate Readings (ዓዲ)`,
                commemoration: daily2014.commemoration,
                dayNode: daily2014,
                fallbackDayNode: daily2014,
                convertLxxFn,
                useAlt: true
            }));
        }
    };

    // 2. If Fixed Feast of Our Lord overrides Sunday, place Daily Feast first, then Sunday options!
    if (wd === 0 && isFixedLordFeastOverridingSunday && profiles.length === 0) {
        appendDaily2014(true);
    }

    // 3. Seasonal Sunday Readings (when weekday === Sunday)
    if (wd === 0) {
        const sunMatches = getEotc2014SundayMatches(y, m, d, 0);
        if (sunMatches.primary) {
            const pSec = sunMatches.primary;
            // Special rubric: 8th Sunday of Tinsae (Pentecost / Paraclete) has empty liturgy -> "say the Resurrection reading!"
            if (!pSec.qidase && pSec.source === 'sunday_trinsae' && pSec.rule.ordinal === 8) {
                const tinsaeDay = EOTC_GITSAWE_2014_FASTS.abiyTsom?.days?.find(x => x.dayOffset === 55);
                const tinsaeQidaseSub = tinsaeDay?.groups?.[1]?.sections?.[0];
                if (tinsaeQidaseSub && tinsaeQidaseSub.qidase) {
                    addProfile(_buildProfileFromDayNode({
                        id: 'sunday-pentecost-tinsae',
                        category: 'sunday',
                        shortLabel: 'Pentecost (Tinsae)',
                        shortLabelGeez: 'ጰራቅሊጦስ',
                        subtitle: `${pSec.sectionIdentifier} • የትንሣኤን ምንባብ በል`,
                        commemoration: pSec.commemoration || pSec.sectionIdentifier,
                        dayNode: tinsaeQidaseSub,
                        fallbackDayNode: daily2014,
                        convertLxxFn
                    }));
                }
            } else if (pSec.qidase) {
                addProfile(_buildProfileFromDayNode({
                    id: `sunday-${pSec.index}`,
                    category: 'sunday',
                    shortLabel: _formatSundayShortLabel(pSec, ''),
                    shortLabelGeez: pSec.commemoration || 'ዘሰንበት',
                    subtitle: `${pSec.sectionIdentifier}${pSec.commemoration ? ' — ' + pSec.commemoration : ''}`,
                    commemoration: pSec.commemoration || pSec.sectionIdentifier,
                    dayNode: pSec,
                    fallbackDayNode: daily2014,
                    convertLxxFn
                }));
                if (pSec.qidase.alt) {
                    addProfile(_buildProfileFromDayNode({
                        id: `sunday-${pSec.index}-alt`,
                        category: 'sunday-alt',
                        shortLabel: `${_formatSundayShortLabel(pSec, '')} · ዓዲ`,
                        shortLabelGeez: 'ዓዲ',
                        subtitle: `${pSec.sectionIdentifier} — Alternate (ዓዲ)`,
                        commemoration: pSec.commemoration,
                        dayNode: pSec,
                        fallbackDayNode: daily2014,
                        convertLxxFn,
                        useAlt: true
                    }));
                }
            }

            // Append alternate Sunday Mezmur options (e.g. Tach Bet / Lay Bet adjacent Mezmur in Tsige/seasons!)
            for (const altItem of sunMatches.alternates) {
                const aSec = altItem.section;
                const housePrefix = altItem.reason.includes('Tach Bet')
                    ? 'Tach Bet'
                    : (altItem.reason.includes('Lay Bet') ? 'Lay Bet' : 'Alt Sunday');
                addProfile(_buildProfileFromDayNode({
                    id: `sunday-alt-${aSec.index}`,
                    category: 'sunday-alt',
                    shortLabel: _formatSundayShortLabel(aSec, housePrefix),
                    shortLabelGeez: aSec.commemoration || '',
                    subtitle: `${altItem.reason}: ${aSec.sectionIdentifier}${aSec.commemoration ? ' — ' + aSec.commemoration : ''}`,
                    commemoration: aSec.commemoration || aSec.sectionIdentifier,
                    dayNode: aSec,
                    fallbackDayNode: daily2014,
                    convertLxxFn
                }));
            }
        }
    }

    // 4. Append Fixed Daily 2014 Gitsawe (primary on ordinary Mon–Sat, or parish Tabot/Saint option on Sundays & Fasts!)
    appendDaily2014(profiles.length === 0);

    // 5. Append 1938 Legacy Edition set(s) ONLY if their Qidase readings differ from all 2014 profiles above!
    const legacy = legacy1938Entry || (typeof window !== 'undefined' && typeof window.getEotcLectionaryEntry === 'function'
        ? window.getEotcLectionaryEntry(m, d)
        : null);
    if (legacy && legacy.qidase && Array.isArray(legacy.qidase.sets)) {
        const toMt = (lxx) => {
            if (!lxx) return null;
            if (typeof convertLxxFn === 'function') return convertLxxFn(lxx);
            if (typeof window !== 'undefined' && typeof window.convertLxxPsalmRefToMt === 'function') {
                return window.convertLxxPsalmRefToMt(lxx);
            }
            return null;
        };
        legacy.qidase.sets.forEach((s, idx) => {
            const legMornPs = (legacy.matins && legacy.matins.psalmLxx && toMt(legacy.matins.psalmLxx)) || DEFAULT_MATINS_REFS.morningPsalm;
            const legMornGo = (legacy.matins && legacy.matins.gospel) || DEFAULT_MATINS_REFS.morningGospel;
            const legRefs = {
                morningPsalm: legMornPs,
                morningGospel: legMornGo,
                pauline: s.pauline || legacy.qidase.pauline,
                universal: s.universal || legacy.qidase.universal,
                acts: s.acts || legacy.qidase.acts,
                psalm: toMt(s.psalmLxx) || 'Psalms 118:26-27',
                gospel: s.gospel,
                eveningPsalm: DEFAULT_MATINS_REFS.eveningPsalm,
                eveningGospel: DEFAULT_MATINS_REFS.eveningGospel
            };
            addProfile({
                id: `legacy-1938-${idx}`,
                category: 'legacy-1938',
                shortLabel: legacy.qidase.sets.length > 1 ? `1938 Ed. (${idx + 1})` : '1938 Ed.',
                shortLabelGeez: '፲፱፻፴፰',
                subtitle: `1938 E.C. Prayer Book Lectionary${legacy.qidase.sets.length > 1 ? ` — Set ${idx + 1}` : ''}`,
                commemoration: '',
                anaphoraId: legacy.qidase.anaphora || 1,
                anaphoraAlts: [],
                liturgyTypeGeez: '',
                psalmLxx: s.psalmLxx,
                refs: legRefs,
                psalmMeta: {
                    psalm: _parseLxxStringMeta(s.psalmLxx, '')
                },
                slotAlternates: {}
            });
        });
    }

    return profiles;
}

if (typeof window !== 'undefined') {
    window.EOTC_BAHIRE_HASAB_CONFIG = EOTC_BAHIRE_HASAB_CONFIG;
    window.EOTC_FEASTS_REGISTRY = EOTC_FEASTS_REGISTRY;
    window.EOTC_MONTHLY_SAINTS = EOTC_MONTHLY_SAINTS;
    window.EOTC_GITSAWE_2014_DAILY = EOTC_GITSAWE_2014_DAILY;
    window.EOTC_GITSAWE_2014_SUNDAYS = EOTC_GITSAWE_2014_SUNDAYS;
    window.EOTC_GITSAWE_2014_FASTS = EOTC_GITSAWE_2014_FASTS;
    window.isEthiopianLeapYear = isEthiopianLeapYear;
    window.computeEotcBahireHasab = computeEotcBahireHasab;
    window.getEotc2014FeastsForDate = getEotc2014FeastsForDate;
    window.getEotc2014SpecialFastMatch = getEotc2014SpecialFastMatch;
    window.getEotcFastingStatus = getEotcFastingStatus;
    window.getEotc2014SundayMatches = getEotc2014SundayMatches;
    window.getEotc2014DailyEntry = getEotc2014DailyEntry;
    window.getEotcKidaseProfilesForDate = getEotcKidaseProfilesForDate;
}

if (typeof module !== 'undefined' && module.exports) {
    module.exports = {
        EOTC_BAHIRE_HASAB_CONFIG,
        EOTC_FEASTS_REGISTRY,
        EOTC_MONTHLY_SAINTS,
        EOTC_GITSAWE_2014_DAILY,
        EOTC_GITSAWE_2014_SUNDAYS,
        EOTC_GITSAWE_2014_FASTS,
        isEthiopianLeapYear,
        computeEotcBahireHasab,
        getEotc2014FeastsForDate,
        getEotc2014SpecialFastMatch,
        getEotcFastingStatus,
        getEotc2014SundayMatches,
        getEotc2014DailyEntry,
        getEotcKidaseProfilesForDate
    };
}
